sp_widget.client_script:
api.controller = function($scope, $location, $anchorScroll) {

  /* =========================================================
     GATENOW LANDING · HERO · Client script
     ========================================================= */

  var c = this;

  /* When the secondary link is an on-page anchor such as
     #how-applying-works, scroll to that section instead of
     letting the browser jump and rewrite the portal URL. */
  c.onSecondary = function(event) {

    var target = c.data.secondaryUrl;

    if (!target || target.charAt(0) !== '#') return;

    event.preventDefault();

    var id = target.substring(1);
    var el = document.getElementById(id);

    if (el && el.scrollIntoView) {
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    } else {
      $location.hash(id);
      $anchorScroll();
    }
  };

}

sp_widget.css:
/* =========================================================
   GATENOW LANDING · HERO
   Service Portal widget · CSS / SCSS

   Selectors are written out in full. The Service Portal Sass
   compiler does not support parent selector concatenation
   (&__line, &--primary).
   ========================================================= */

/* ---------- typeface ----------
   Self hosted so the widget makes no external request. Upload the
   four Outfit woff2 files as Image records (db_image) inside this
   scoped application, named exactly as referenced below. Images in
   a scoped app are served from the instance at /<name>, so these
   URLs stay valid on any instance the app is installed on.

   Outfit is licensed under the SIL Open Font License 1.1, which
   permits redistribution. Attach OFL.txt to the application before
   submitting, since the Store review checks bundled font licences.

   If the files are not uploaded, nothing breaks. The stack below
   falls through to the platform UI font.
   ------------------------------------------------------------- */

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_regular.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_medium.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_semibold.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_bold.woff2") format("woff2");
}


/* ---------- palette ---------- */
$gnl-navy:      #0a2540;   // headline, dark text
$gnl-blue:      #1560e0;   // primary accent
$gnl-blue-dk:   #0f4cbb;   // pressed state
$gnl-blue-soft: #e8f0fe;   // tinted fills
$gnl-body:      #55677f;   // supporting copy
$gnl-white:     #ffffff;

$gnl-shadow-soft: 0 12px 30px rgba(16, 54, 110, 0.10);
$gnl-shadow-btn:  0 14px 30px rgba(21, 96, 224, 0.30);

$gnl-font: "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;


/* =========================================================
   SECTION
   ========================================================= */

.gnl-hero {
  position: relative;
  width: 100%;
  padding: 112px 24px 130px;
  font-family: $gnl-font;
  color: $gnl-navy;
  text-align: center;
  overflow: hidden;
  background-color: #f2f7fe;
  background-image:
    radial-gradient(900px 520px at 50% -12%, rgba(206, 226, 252, 0.85), rgba(206, 226, 252, 0) 70%),
    radial-gradient(760px 520px at 100% 42%, rgba(214, 231, 253, 0.70), rgba(214, 231, 253, 0) 66%),
    radial-gradient(680px 460px at 0% 76%, rgba(226, 238, 253, 0.75), rgba(226, 238, 253, 0) 64%),
    linear-gradient(180deg, #f4f8fe 0%, #e9f1fd 52%, #f3f8fe 100%);
}

.gnl-hero *,
.gnl-hero *::before,
.gnl-hero *::after { box-sizing: border-box; }

/* No element level margin reset here. A selector such as
   .gnl-hero p outranks .gnl-sub and would silently cancel its
   margin. Margins are set on the component classes instead. */

.gnl-hero a { text-decoration: none; }
.gnl-hero a:hover,
.gnl-hero a:focus { text-decoration: none; }

.gnl-hero :focus-visible {
  outline: 2px solid $gnl-blue;
  outline-offset: 3px;
}

.gnl-hero__inner {
  max-width: 1080px;
  margin: 0 auto;
}


/* =========================================================
   HEADLINE
   ========================================================= */

.gnl-hero .gnl-title {
  margin: 0;
  font-size: 88px;
  font-weight: 700;
  line-height: 1.14;
  letter-spacing: -0.028em;
  color: $gnl-navy;
}

@supports (font-size: clamp(38px, 6.1vw, 88px)) {
  .gnl-hero .gnl-title { font-size: clamp(38px, 6.1vw, 88px); }
}

.gnl-title__line { display: block; }

.gnl-title__accent { color: $gnl-blue; }

/* the full stops stay navy even on the accented line, and the
   negative tracking is cancelled so they do not crowd the word */
.gnl-title__stop {
  color: $gnl-navy;
  margin-left: 0.05em;
  letter-spacing: 0;
}


/* =========================================================
   SUPPORTING COPY
   ========================================================= */

.gnl-hero .gnl-sub {
  display: block;
  max-width: 742px;
  margin: 46px auto 0;
  padding: 0;
  font-size: 20px;
  font-weight: 400;
  line-height: 1.58;
  letter-spacing: -0.005em;
  color: $gnl-body;
}


/* =========================================================
   CALLS TO ACTION
   ========================================================= */

.gnl-hero .gnl-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 24px;
  margin-top: 58px;
}

.gnl-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  height: 72px;
  padding: 0 44px;
  border-radius: 999px;
  font-size: 17.5px;
  font-weight: 600;
  letter-spacing: -0.01em;
  transition: background 0.22s ease, box-shadow 0.22s ease, transform 0.22s ease, color 0.22s ease;
}

.gnl-btn--primary {
  background: $gnl-blue;
  color: $gnl-white;
  box-shadow: $gnl-shadow-btn;
}

.gnl-btn--primary:hover {
  background: $gnl-blue-dk;
  color: $gnl-white;
  box-shadow: 0 18px 38px rgba(21, 96, 224, 0.38);
  transform: translateY(-2px);
}

.gnl-btn--ghost {
  background: $gnl-white;
  color: $gnl-navy;
  padding: 0 42px 0 17px;
  box-shadow: $gnl-shadow-soft;
}

.gnl-btn--ghost:hover {
  color: $gnl-navy;
  box-shadow: 0 16px 36px rgba(16, 54, 110, 0.16);
  transform: translateY(-2px);
}

.gnl-play {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: $gnl-blue-soft;
  color: $gnl-blue;
  font-size: 11px;
  flex-shrink: 0;
}

.gnl-play i { margin-left: 2px; }


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 900px) {
  .gnl-hero { padding: 76px 20px 92px; }
  .gnl-hero .gnl-sub { font-size: 18px; margin-top: 34px; }
  .gnl-hero .gnl-actions { margin-top: 42px; gap: 16px; }
  .gnl-btn { height: 64px; padding: 0 34px; font-size: 16.5px; }
  .gnl-btn--ghost { padding: 0 32px 0 14px; }
}

@media (max-width: 620px) {
  .gnl-hero { padding: 56px 18px 68px; }

  .gnl-hero .gnl-title { letter-spacing: -0.03em; }
  .gnl-hero .gnl-sub { font-size: 16px; }

  .gnl-hero .gnl-actions {
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
  }

  .gnl-btn {
    width: 100%;
    height: 58px;
    font-size: 16px;
  }

  .gnl-btn--ghost { padding: 0 20px; }
}

@media (prefers-reduced-motion: reduce) {
  .gnl-hero * { transition: none; }
  .gnl-btn:hover { transform: none; }
}

sp_widget.script:
(function () {

  /* =========================================================
     GATENOW LANDING · HERO
     Service Portal widget · Server script

     Every string is a widget option with a fallback, so the
     copy can be edited without touching code.
     ========================================================= */

  function opt(name, fallback) {
    var v = (typeof options === 'undefined') ? null : options[name];
    return (v === null || v === undefined || v === '') ? fallback : v;
  }

  /* ---------- copy ---------- */
  data.headlineOne        = opt('headline_one', 'Win the funding');
  data.headlineTwoLead    = opt('headline_two_lead', 'Skip the');
  data.headlineTwoAccent  = opt('headline_two_accent', 'paperwork');
  data.subhead            = opt('subhead',
    'Everything you need to find the right funding, apply with confidence, and manage your grant journey all in one place, from your first application through award and beyond.');

  /* ---------- actions ---------- */
  data.primaryLabel   = opt('primary_label', "See what's open");
  data.primaryUrl     = opt('primary_url', '?id=opportunities');
  data.secondaryLabel = opt('secondary_label', 'How applying works');
  data.secondaryUrl   = opt('secondary_url', '#how-applying-works');

})();
